<script setup lang="ts">
import {onMounted,reactive,ref} from 'vue';import{useRouter}from'vue-router';import{ElMessage}from'element-plus';import{getReceivingOrder,getReceivingOrderItems,importReceivingOrderExcel,updateReceivingOrder}from'../../api/receivingOrder';import{getSuppliers}from'../../api/supplier';import type{ReceivingOrder,ReceivingOrderItem,Supplier}from'../../api/types';
const props=defineProps<{id:string}>();const router=useRouter();const order=ref<ReceivingOrder>();const items=ref<ReceivingOrderItem[]>([]);const suppliers=ref<Supplier[]>([]);const total=ref(0);const loading=ref(false);const importing=ref(false);const editing=ref(false);const fileInput=ref<HTMLInputElement>();const page=reactive({pageNum:0,pageSize:10});const form=reactive({supplierId:undefined as number|undefined,number:undefined as number|undefined,receiveDate:'',temperature:'',transport:''});
async function load(){loading.value=true;try{order.value=await getReceivingOrder(Number(props.id));const d=await getReceivingOrderItems({orderId:Number(props.id),...page});items.value=d.list||[];total.value=d.total||0;Object.assign(form,{supplierId:order.value.supplierId,number:order.value.number,receiveDate:order.value.receiveDate,temperature:order.value.temperature||'',transport:order.value.transport||''})}catch(e:any){ElMessage.error(e.message||'加载失败')}finally{loading.value=false}}
async function loadSuppliers(){const d=await getSuppliers({pageNum:0,pageSize:20});suppliers.value=d.list||[]}function selectFile(){fileInput.value?.click()}async function onFileChange(e:Event){const input=e.target as HTMLInputElement;const f=input.files?.[0];if(!f)return;importing.value=true;try{const r=await importReceivingOrderExcel(Number(props.id),f);ElMessage.success(`导入完成${r?.success!==undefined?'：成功 '+r.success:''}`);page.pageNum=0;await load()}catch(e:any){ElMessage.error(e.message||'导入失败')}finally{importing.value=false;input.value=''}}
async function save(){if(!form.supplierId)return ElMessage.warning('请选择供应商');try{await updateReceivingOrder(Number(props.id),{supplierId:form.supplierId,number:form.number,receiveDate:form.receiveDate,temperature:form.temperature,transport:form.transport});editing.value=false;ElMessage.success('修改成功');await load()}catch(e:any){ElMessage.error(e.message||'修改失败')}}
function cs(v?:string){return({UNCHECKED:'未点货',PASS:'通过',FAIL:'异常'}as any)[v||'']||'-'}onMounted(()=>{load();loadSuppliers()})
</script>
<template><div><div class="page-title"><div><h2>收货单详情</h2><p>收货单 #{{id}}</p></div><div><el-button @click="router.back()">返回</el-button><el-button @click="selectFile" :loading="importing">导入 Excel</el-button><el-button type="primary" @click="editing=true">修改</el-button><el-button v-if="order?.progress!=='COMPLETED'" type="success" @click="router.push(`/receiving-orders/${id}/check`)">开始点货</el-button><input ref="fileInput" type="file" accept=".xlsx,.xls" hidden @change="onFileChange"/></div></div><el-card shadow="never" class="mb16"><el-descriptions :column="4" border><el-descriptions-item label="供应商">{{order?.supplierName||'-'}}</el-descriptions-item><el-descriptions-item label="Number">{{order?.number??'-'}}</el-descriptions-item><el-descriptions-item label="收货日期">{{order?.receiveDate||'-'}}</el-descriptions-item><el-descriptions-item label="进度">{{order?.progress||'-'}}</el-descriptions-item><el-descriptions-item label="温度">{{order?.temperature||'-'}}</el-descriptions-item><el-descriptions-item label="运输公司">{{order?.transport||'-'}}</el-descriptions-item></el-descriptions></el-card><el-card shadow="never"><template #header>货单明细</template><el-table :data="items" v-loading="loading" stripe><el-table-column prop="supplierCode" label="货号" width="140"/><el-table-column prop="productName" label="商品名称" min-width="220"/><el-table-column prop="orderQty" label="订单箱数" width="100"/><el-table-column prop="actualQty" label="实际箱数" width="100"/><el-table-column prop="barcode" label="Barcode" min-width="150"/><el-table-column prop="expiryDate" label="有效期" width="150"/><el-table-column prop="category" label="类型" width="120"/><el-table-column prop="sugar" label="糖等级" width="90"/><el-table-column prop="unitPrice" label="单价" width="90"/><el-table-column label="点货状态" width="100"><template #default="{row}"><el-tag :type="row.checkStatus==='PASS'?'success':row.checkStatus==='FAIL'?'danger':'info'">{{cs(row.checkStatus)}}</el-tag></template></el-table-column></el-table><div class="pagination"><el-pagination :current-page="page.pageNum+1" :page-size="page.pageSize" :total="total" layout="total,prev,pager,next" @current-change="(p:number)=>{page.pageNum=p-1;load()}"/></div></el-card><el-dialog v-model="editing" title="修改收货单" width="520px"><el-form label-width="90px"><el-form-item label="供应商" required><el-select v-model="form.supplierId" style="width:100%"><el-option v-for="s in suppliers" :key="s.id" :label="s.supplierName" :value="s.id"/></el-select></el-form-item><el-form-item label="Number"><el-input-number v-model="form.number" :min="0" :precision="0"/></el-form-item><el-form-item label="收货日期"><el-date-picker v-model="form.receiveDate" type="date" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="温度"><el-input v-model="form.temperature"/></el-form-item><el-form-item label="运输公司"><el-input v-model="form.transport"/></el-form-item></el-form><template #footer><el-button @click="editing=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div></template>